-- New EMPTY LOCAL staging rehearsal only. All fixtures, reviews and requests roll back.
begin;
select plan(35);
select ok((select relrowsecurity from pg_class where oid='app_private.customer_source_events'::regclass),'source intent is protected by RLS');
select ok((select relrowsecurity from pg_class where oid='app_private.change_order_response_requests'::regclass),'response receipts are protected by RLS');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) r cross join unnest(array['app_private.customer_source_events','app_private.change_order_response_requests']) t cross join unnest(array['select','insert','update','delete','truncate','references','trigger']) p where has_table_privilege(r,t,p)),'no API role has direct source or receipt table privileges');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_sequence_privilege(r,'app_private.customer_source_events_event_order_seq','usage') or has_sequence_privilege(r,'app_private.customer_source_events_event_order_seq','select') or has_sequence_privilege(r,'app_private.customer_source_events_event_order_seq','update')),'identity sequence has no direct API privileges');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_function_privilege(r,'app_private.capture_customer_source_event()','execute')),'trigger helper is not a callable API');
select is((select count(*)::integer from unnest(array['public.find_customer_source_event(text)','public.get_customer_source_event(uuid)','public.prepare_customer_source_event(uuid,jsonb,text,uuid)','public.record_invoice_preference_with_event(text,text)','public.respond_to_change_order_by_portal(uuid,text,timestamptz,text,text)']) f where has_function_privilege('service_role',f,'execute')),5,'all five server commands have exact service execution');
select ok(not exists(select 1 from unnest(array['anon','authenticated']) r cross join unnest(array['public.find_customer_source_event(text)','public.get_customer_source_event(uuid)','public.prepare_customer_source_event(uuid,jsonb,text,uuid)','public.record_invoice_preference_with_event(text,text)','public.respond_to_change_order_by_portal(uuid,text,timestamptz,text,text)']) f where has_function_privilege(r,f,'execute')),'browser and anonymous roles cannot call server commands');
select is((select count(*)::integer from unnest(array['public.list_pending_customer_source_events(integer)','public.review_customer_source_event(uuid,uuid,text)']) f where has_function_privilege('authenticated',f,'execute')),2,'signed-in review commands retain narrow grants');
select ok(not exists(select 1 from unnest(array['anon','service_role']) r cross join unnest(array['public.list_pending_customer_source_events(integer)','public.review_customer_source_event(uuid,uuid,text)']) f where has_function_privilege(r,f,'execute')),'non-user roles cannot authorize operator reviews');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where ((n.nspname='app_private' and p.proname='capture_customer_source_event') or (n.nspname='public' and p.proname in ('find_customer_source_event','get_customer_source_event','prepare_customer_source_event','record_invoice_preference_with_event','respond_to_change_order_by_portal','list_pending_customer_source_events','review_customer_source_event'))) and 'search_path=""'=any(proconfig)),8,'all eight new routines pin an empty search path');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select public.find_customer_source_event('guess')$$,'42501',null,'actual anonymous invocation denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.list_pending_customer_source_events()$$,'42501',null,'no subject cannot review');
select throws_ok($$select public.prepare_customer_source_event(null,'{}')$$,'42501',null,'actual signed-in role cannot prepare via service RPC');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role","sub":"f9600000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.find_customer_source_event('guess')$$,'42501',null,'service key with end-user subject cannot impersonate background authority');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select * from app_private.customer_source_events$$,'42501',null,'actual service role cannot read private source table');
reset role;
insert into roles(name) values('owner'),('crew') on conflict(name) do nothing;
insert into auth.users(id,email,raw_user_meta_data) values
 ('f9600000-0000-0000-0000-000000000001','staging96-owner@example.invalid','{}'),
 ('f9600000-0000-0000-0000-000000000002','staging96-crew@example.invalid','{}');
update profiles set status='active',full_name='Synthetic staging96' where id::text like 'f9600000-%';
insert into user_roles(user_id,role_id) select 'f9600000-0000-0000-0000-000000000001',id from roles where name='owner';
insert into user_roles(user_id,role_id) select 'f9600000-0000-0000-0000-000000000002',id from roles where name='crew';
insert into customers(id,display_name,email) values('f9610000-0000-0000-0000-000000000001','Synthetic staging96','staging96-customer@example.invalid');
insert into service_locations(id,customer_id,street,city,state) values('f9610000-0000-0000-0000-000000000002','f9610000-0000-0000-0000-000000000001','123 Synthetic Lane','Fredericksburg','VA');
create temporary table source_probe(kind text primary key,r jsonb);
grant select,insert,update on source_probe to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f9600000-0000-0000-0000-000000000001"}',true);
insert into source_probe values('quote',public.create_quote_draft('{"customer_id":"f9610000-0000-0000-0000-000000000001","service_location_id":"f9610000-0000-0000-0000-000000000002"}','[{"name":"Synthetic service","quantity":1,"unit_price_cents":1000,"total_cents":1000}]'));
reset role;
insert into quote_portal_tokens(quote_id,customer_id,token_hash,expires_at) select (r->>'id')::uuid,'f9610000-0000-0000-0000-000000000001',repeat('a',64),clock_timestamp()+interval '1 day' from source_probe where kind='quote';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into source_probe values('response',public.request_quote_changes_by_portal('f9620000-0000-0000-0000-000000000001',repeat('a',64),(select (r->>'edit_revision')::integer from source_probe where kind='quote'),'Synthetic local request requiring durable handoff'));
reset role;
select is((select count(*)::integer from app_private.customer_source_events),1,'source audit transaction captures one intent');
select is((select count(*)::integer from notes where body like 'Customer portal change request: Synthetic local%'),1,'original required customer note is committed with intent');
select is((select count(*)::integer from app_private.customer_source_events where prepared_activity_id is null),1,'uninvoked preparation remains recoverable');
select is((select count(*)::integer from app_private.outbound_deliveries),0,'source commit alone never prepares or dispatches mail');
insert into source_probe select 'source',jsonb_build_object('id',id,'hash',event_hash,'body',event->>'body') from app_private.customer_source_events;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f9600000-0000-0000-0000-000000000002"}',true);
select throws_ok($$select public.list_pending_customer_source_events()$$,'42501',null,'crew cannot inspect recovery queue');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f9600000-0000-0000-0000-000000000001"}',true);
select is(public.list_pending_customer_source_events()->>'total','1','active owner sees one pending event');
select ok(not (public.list_pending_customer_source_events()->'events'->0 ? 'event') and not(public.list_pending_customer_source_events()->'events'->0 ? 'body'),'pending queue does not disclose raw source payload');
insert into source_probe select 'review',public.review_customer_source_event((r->>'id')::uuid,'f9620000-0000-0000-0000-000000000002','Synthetic local recovery review') from source_probe where kind='source';
reset role;
update customers set display_name='Changed after source commit' where id='f9610000-0000-0000-0000-000000000001';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.prepare_customer_source_event((r->>'id')::uuid,'{"from":"office@example.invalid","reply_to":"office@example.invalid"}',null,'f9620000-0000-0000-0000-000000000099') from source_probe where kind='source'$$,'42501',null,'different review acknowledgement is refused');
insert into source_probe select 'prepared',public.prepare_customer_source_event((r->>'id')::uuid,'{"from":"office@example.invalid","reply_to":"office@example.invalid"}',null,'f9620000-0000-0000-0000-000000000002') from source_probe where kind='source';
select lives_ok($$select public.prepare_customer_source_event((r->>'id')::uuid,'{"from":"office@example.invalid","reply_to":"office@example.invalid"}',null,'f9620000-0000-0000-0000-000000000002') from source_probe where kind='source'$$,'same reviewed preparation replays safely');
reset role;
select is((select count(*)::integer from app_private.customer_activity_preparations),1,'one preparation after replay');
select is((select count(*)::integer from app_private.outbound_deliveries),1,'one saved office email after replay');
select is((select sum(attempt_count)::integer from app_private.outbound_deliveries),0,'reviewed preparation performs no provider attempt');
select ok((select prepared_activity_id is not null and prepared_at is not null from app_private.customer_source_events),'source acknowledgement is saved with full preparation');
select is((select event_hash from app_private.customer_source_events),(select r->>'hash' from source_probe where kind='source'),'later customer edits do not change frozen source facts');
select is((select event->>'body' from app_private.customer_source_events),'Synthetic local request requiring durable handoff','original customer wording remains frozen');
select is((select count(*)::integer from email_events),0,'no simulated or actual provider receipt in no-send recovery');
update profiles set status='disabled' where id='f9600000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f9600000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.list_pending_customer_source_events()$$,'42501',null,'disabled owner loses recovery access');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.prepare_customer_source_event((r->>'id')::uuid,'{"from":"office@example.invalid","reply_to":"office@example.invalid"}',null,'f9620000-0000-0000-0000-000000000002') from source_probe where kind='source'$$,'42501',null,'offboarded review authority cannot prepare even on replay');
reset role;
select ok(has_function_privilege('supabase_auth_admin','ats_staging_auth.reject_email(jsonb)','execute'),'Auth service retains guard execution');
select is(ats_staging_auth.reject_email('{"synthetic":"staging96-no-send"}'::jsonb)->'error'->'http_code','503'::jsonb,'Auth hook still refuses synthetic delivery without provider I/O');
select * from finish();
rollback;
